"""Derives Test-ClientNativeDamage-v1275.ps1 from Test-HostNativeDamage-v1274.ps1 for stage 4 (#14, 1214y): the client
player's own grenade explosion on a host-owned, combat-bound guard. Before 1214y the client capture suppressed such damage
and retired the guard, so a client grenade, power or bolt variant never hurt a host NPC. The lab-only
`coop_npc_combat hostnative_test`, run on the client, sends the native explosion_grenade (attacker and inflictor the
client player) through the client's installed damage observer at its nearest bound replica. Pass (runtime): the client
sends a PeerNative request, the host applies it natively (avatar as attacker), and the guard ends in the same state in
both worlds (HostWorld or Dead)."""
from pathlib import Path
P = Path(__file__).resolve().parent
s = P.joinpath('Test-HostNativeDamage-v1274.ps1').read_bytes().decode('utf-8')
def rep(old, new, count=1):
    global s
    assert s.count(old) == count, (s.count(old), old[:70]); s = s.replace(old, new)
rep("[string]$Take='hostnative-damage-v1274a',[string]$Candidate='candidate-npc-combat-v1214x',[int]$Hits=1)",
    "[string]$Take='clientnative-damage-v1275a',[string]$Candidate='candidate-npc-combat-v1214y',[int]$Hits=1)")
rep("# 1274 (stage 4, #14, 1214x): the host player's own grenade explosion on a combat-bound guard. Generated by make_hostnative_damage_v1274.py from 1248l.",
    "# 1275 (stage 4, #14, 1214y): the client player's own grenade explosion on a host-owned bound guard. Generated by make_clientnative_damage_v1275.py from 1274.")
rep("operation='HostNative1274'", "operation='ClientNative1275'", 2)
rep("C host 'coop_npc_combat hostnative_test';",
    "C client ('setviewpos {0} {1} {2} 0 0' -f (F ([double]$og.position[0]-1.8)),(F ([double]$og.position[1])),(F ([double]$og.position[2]+1.7)));Start-Sleep -Milliseconds 700;C client 'coop_npc_combat hostnative_test';")
rep("$t=S host '.npc-hostworld-test.json';", "$t=S client '.npc-hostworld-test.json';")
rep("host=($hc|Select-Object result,hostNativePassed,hostNativeLast,hostWorldCommitted,committed,deaths,lastRetire);client=($cc|Select-Object result,hostWorldApplied,followSubtractions,applied,deaths,lastRetire);",
    "host=($hc|Select-Object result,peerNativeApplied,hostWorldCommitted,committed,deaths,lastRetire);client=($cc|Select-Object result,peerNativeRequests,peerNativeBusy,hostWorldApplied,followSubtractions,applied,deaths,lastRetire);")
rep("if($t.target-ne$g.handle){throw \"Hit $i targeted $($t.target), not the tutorial guard $($g.handle) ($($t.result))\"}",
    "if($t.target-ne$og.handle){throw \"Hit $i targeted $($t.target), not the tutorial guard replica $($og.handle) ($($t.result))\"}")
rep("if($t.result-ne'damaged'-or$t.mode-ne'hostnative'){", "if($t.mode-ne'clientnative'-or$t.result-notin'damaged','unchanged'-or!($null-eq$after.host-or[double]$after.host-lt[double]$before.host)){")
# 1275c: the client suppresses its own hit by design (the fixture reads unchanged); the host world must lose health.
rep("host grenade damage not applied ($($t.mode) $($t.result))", "client grenade damage not applied on the host ($($t.mode) $($t.result), host $($before.host) -> $($after.host))")
rep("""  $row.counters=[ordered]@{hostNativePassed=$hc.hostNativePassed;hostNativeLast=$hc.hostNativeLast;hostWorldCommitted=$hc.hostWorldCommitted;clientHostWorldApplied=$cc.hostWorldApplied}""",
    """  $row.counters=[ordered]@{clientPeerNativeRequests=$cc.peerNativeRequests;clientPeerNativeBusy=$cc.peerNativeBusy;hostPeerNativeApplied=$hc.peerNativeApplied;hostWorldCommitted=$hc.hostWorldCommitted;clientHostWorldApplied=$cc.hostWorldApplied}""")
rep("""  if($hc.hostNativePassed-lt$Hits-or$hc.hostNativeLast-ne'components/equipment/damage/explosion_grenade.damage'){throw "The host capture did not pass the grenade natively ($($hc.hostNativePassed), $($hc.hostNativeLast))"}""",
    """  if($cc.peerNativeRequests-lt$Hits-or$hc.peerNativeApplied-lt$Hits){throw "PeerNative requests $($cc.peerNativeRequests), applied on the host $($hc.peerNativeApplied), expected $Hits"}""")
rep("$row.checks.Add('The host grenade explosion passed the capture natively (hostNativePassed) and the guard ends in the same state in both worlds')",
    "$row.checks.Add('The client grenade explosion became a PeerNative request the host applied natively; the guard ends in the same state in both worlds')")
rep('Save "$out/hostnative.json"', 'Save "$out/clientnative.json"')
rep("try{Restore 'hostnative';", "try{Restore 'clientnative';")
rep("scope='Stage 4 host player damage the replay cannot reproduce: under the product controller the lab-only hostnative_test sends the native grenade explosion (local player as attacker and inflictor) to the combat-bound Dunwall tutorial guard through the installed damage observer; it must apply natively and the guard end in the same state in both worlds (1214w/1214x); fixture restored.'",
    "scope='Stage 4 client player damage the replay cannot reproduce: under the product controller the lab-only hostnative_test on the client sends the native grenade explosion (client player as attacker and inflictor) at its bound replica of the Dunwall tutorial guard; it must become a PeerNative request the host applies natively, and the guard end in the same state in both worlds (1214y); fixture restored.'")
rep('"PASS_HOSTNATIVE_DAMAGE"', '"PASS_CLIENTNATIVE_DAMAGE"')
P.joinpath('Test-ClientNativeDamage-v1275.ps1').write_bytes(s.encode('utf-8'))
print('ok')
